// The panorama viewer of the phones, tablets, computers and TVs on a 360° panorama a computer generated beyond the edges
// of a photo (design-final 2026-10-27, section 5, points 1, 3 and 4, lot P4): it opens on the photo itself (the
// centre column, our panoramas writing no initial view), keeps the "360° AI" badge, and says "Generated by AI beyond
// the photo's edges" for a few seconds while the photo is outlined. Our packet comes from the head the GPano read goes
// through for a file, and from the head of the original for a photo on the server.

import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:immich_mobile/domain/services/spherical_probe.dart';
import 'package:immich_mobile/domain/services/store.service.dart';
import 'package:immich_mobile/presentation/widgets/asset_viewer/panorama_viewer.widget.dart';
import 'package:immich_mobile/providers/infrastructure/immersive.provider.dart';
import 'package:immich_mobile/providers/infrastructure/store.provider.dart';

import '../../../domain/ai_immersive/stereo_photo_fixtures.dart';
import '../../../unit/factories/remote_asset_factory.dart';
import '../../../unit/presentation/presentation_context.dart';
import '../../../widget_tester_extensions.dart';

/// Yields [image] once, a little later, as an image from the network would
class _TestImageProvider extends ImageProvider<_TestImageProvider> {
  const _TestImageProvider(this.image);

  final ui.Image image;

  @override
  Future<_TestImageProvider> obtainKey(ImageConfiguration configuration) => Future.value(this);

  @override
  ImageStreamCompleter loadImage(_TestImageProvider key, ImageDecoderCallback decode) =>
      OneFrameImageStreamCompleter(Future.value(ImageInfo(image: image.clone())));
}

void main() {
  late PresentationContext context;
  late List<(int, int)> reads;

  final panoramaSample = File('test/fixtures/ai_immersive/xmp_v1_panorama_sample.xmp').readAsStringSync();
  final stereoSample = File('test/fixtures/ai_immersive/xmp_v1_stereo_panorama_sample.xmp').readAsStringSync();
  const honesty = "Generated by AI beyond the photo's edges";
  final badge = find.byKey(const Key('panorama_generated_badge'));
  final outline = find.byKey(const Key('panorama_photo_region'));

  String withField(String packet, String field, String value) =>
      packet.replaceFirst(RegExp('Immuch360:$field="[^"]*"'), 'Immuch360:$field="$value"');

  setUp(() async {
    context = await PresentationContext.create();
    reads = [];
  });

  tearDown(() async {
    await context.dispose();
  });

  ByteRangeReader reader(Uint8List bytes) => (offset, length) async {
    reads.add((offset, length));
    final start = math.min(offset, bytes.length);
    return Uint8List.sublistView(bytes, start, math.min(start + length, bytes.length));
  };

  /// The viewer on the file [file] of a share named [name]
  Future<void> pumpSource(WidgetTester tester, {required String name, required Uint8List file}) async {
    final image = (await tester.runAsync(() => createTestImage(width: 64, height: 32)))!;
    addTearDown(image.dispose);
    final PanoramaSource source = (
      image: _TestImageProvider(image),
      name: name,
      length: file.length,
      read: reader(file),
    );
    await tester.pumpConsumerWidget(
      PanoramaViewerPage.source(source: source),
      overrides: [
        storeServiceProvider.overrideWithValue(StoreService.I),
        isHorizonOsProvider.overrideWith((ref) => false),
      ],
    );
  }

  PanoramaViewProbe probe(WidgetTester tester) => tester.state(find.byType(PanoramaViewerPage)) as PanoramaViewProbe;

  testWidgets('a panorama we generated opens on its photo at the centre column, its badge and its sentence shown', (
    tester,
  ) async {
    await pumpSource(
      tester,
      name: 'salon_360.jpg',
      file: jpegFile(width: 8192, height: 4096, xmpText: panoramaSample),
    );
    await tester.pump();

    expect(parseGPanoInitialView(panoramaSample), isNull, reason: 'our panoramas write no initial view');
    expect(probe(tester).view.longitude, 0);
    expect(probe(tester).view.latitude, 0);
    expect(badge, findsOneWidget);
    expect(tester.widget<Text>(badge).data, '360° AI');
    expect(find.byTooltip(honesty), findsOneWidget, reason: 'the badge carries its honesty sentence');
    expect(find.text(honesty), findsOneWidget);
    expect(outline, findsOneWidget);
    expect(find.descendant(of: outline, matching: find.text('The original photo')), findsOneWidget);
    // The packet came with the head the GPano read went through: no read more
    expect(reads.where((read) => read.$1 == 0), hasLength(1));

    // Five seconds, then it fades out; the badge stays
    await tester.pump(const Duration(seconds: 5));
    await tester.pump(const Duration(seconds: 1));
    await tester.pump();
    expect(find.text(honesty), findsNothing);
    expect(find.descendant(of: outline, matching: find.byType(CustomPaint)), findsNothing);
    expect(find.text('The original photo'), findsNothing);
    expect(badge, findsOneWidget);
  });

  test('the outline and its caption are where the sphere shows the photo', () {
    const size = Size(800, 600);
    // The centre of the view, and a point 90° away from it, out of view
    expect(
      projectSpherePoint((longitude: 30, latitude: 10), longitude: 30, latitude: 10, fov: 90, size: size),
      const Offset(400, 300),
    );
    expect(projectSpherePoint((longitude: 120, latitude: 0), longitude: 30, latitude: 0, fov: 90, size: size), isNull);
    // Half the vertical field of view up: the top of the view; to the right of the centre: the right of it
    final up = projectSpherePoint((longitude: 0, latitude: 45), longitude: 0, latitude: 0, fov: 90, size: size)!;
    expect(up.dx, closeTo(400, 1e-9));
    expect(up.dy, closeTo(0, 1e-9));
    final right = projectSpherePoint((longitude: 20, latitude: 0), longitude: 0, latitude: 0, fov: 90, size: size)!;
    expect(right.dx, greaterThan(400));
  });

  testWidgets('a photo turned right of the centre column and looking up opens where it is', (tester) async {
    final turned = withField(withField(panoramaSample, 'PhotoYaw', '30.0'), 'PhotoPitch', '10.0');
    await pumpSource(
      tester,
      name: 'salon_360.jpg',
      file: jpegFile(width: 8192, height: 4096, xmpText: turned),
    );
    await tester.pump();

    expect(probe(tester).view.longitude, 30);
    expect(probe(tester).view.latitude, 10);
  });

  testWidgets('its 3D version shows the left eye with the same badge, sentence and outline', (tester) async {
    await pumpSource(
      tester,
      name: 'salon_360_3D.jpg',
      file: jpegFile(width: 4096, height: 4096, xmpText: stereoSample),
    );
    await tester.pump();

    expect(tester.widget<Text>(badge).data, '360° AI');
    expect(find.text(honesty), findsOneWidget);
    expect(outline, findsOneWidget);
  });

  testWidgets('the 3D version of a 360° photo of the user says its relief was estimated, no outline', (tester) async {
    final user = withField(
      stereoSample,
      'Origin',
      'EstimatedDepth',
    ).replaceFirst(RegExp(r'\s*Immuch360:Relief="[^"]*"'), '');
    await pumpSource(
      tester,
      name: 'trip_360_3D.jpg',
      file: jpegFile(width: 4096, height: 4096, xmpText: user),
    );
    await tester.pump();

    expect(tester.widget<Text>(badge).data, '3D AI');
    expect(find.text('Relief estimated by AI'), findsOneWidget);
    expect(find.text(honesty), findsNothing);
    expect(outline, findsNothing);
  });

  testWidgets('an ordinary 360° photo gets neither badge nor sentence', (tester) async {
    await pumpSource(
      tester,
      name: 'trip.jpg',
      file: jpegFile(width: 8192, height: 4096, segments: [gpanoSegment()]),
    );
    await tester.pump();

    expect(badge, findsNothing);
    expect(find.text(honesty), findsNothing);
    expect(outline, findsNothing);
  });

  testWidgets('a panorama on the server: its packet read from the head of its original, the GPano from the preview', (
    tester,
  ) async {
    final asset = RemoteAssetFactory.create(width: 8192, height: 4096, name: 'salon_360.jpg');
    final original = jpegFile(width: 8192, height: 4096, xmpText: panoramaSample);
    final image = (await tester.runAsync(() => createTestImage(width: 64, height: 32)))!;
    addTearDown(image.dispose);
    final previews = <Uri>[];
    final originals = <String>[];
    await tester.pumpConsumerWidget(
      PanoramaViewerPage(asset: asset),
      overrides: [
        isHorizonOsProvider.overrideWith((ref) => false),
        panoramaImageProvider.overrideWithValue((_, _) => _TestImageProvider(image)),
        panoramaGPanoClientProvider.overrideWithValue(
          MockClient((request) async {
            previews.add(request.url);
            return http.Response.bytes(gpanoSegment(), 206);
          }),
        ),
        panoramaOriginalReaderProvider.overrideWithValue((remoteId) {
          originals.add(remoteId);
          return reader(original);
        }),
      ],
    );
    await tester.pumpAndSettle(const Duration(milliseconds: 100));

    expect(originals, [asset.remoteId]);
    expect(reads, [(0, 131072)]);
    expect(previews, hasLength(1), reason: 'the GPano tags still come from the preview');
    expect(badge, findsOneWidget);
    expect(probe(tester).view.longitude, 0);

    await tester.pump(const Duration(seconds: 7));
  });
}
